 void showEditor(){page="editor";base(projectName);LinearLayout info=row();info.addView(text(String.format(Locale.US,"00:%02d:%02d / 00:00:10",playhead/60,playhead%60),12,MUTED),new LinearLayout.LayoutParams(0,dp(34),1));TextView settings=button("⚙",false);info.addView(settings,new LinearLayout.LayoutParams(dp(48),dp(36)));settings.setOnClickListener(v->showSettings());body.addView(info);stage=new Stage(this);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(240));sp.setMargins(0,dp(8),0,dp(12));body.addView(stage,sp);LinearLayout ctl=row();String[] labels={"▦","Full","|◀","▶","▶|","◈","↶","↷"};for(int i=0;i<labels.length;i++){final int k=i;TextView b=button(labels[i],false);ctl.addView(b,new LinearLayout.LayoutParams(0,dp(44),1));b.setOnClickListener(v->{switch(k){case 0:showGrid=!showGrid;stage.invalidate();break;case 1:Toast.makeText(this,"معاينة "+ratio,Toast.LENGTH_SHORT).show();break;case 2:playhead=Math.max(0,playhead-1);showEditor();break;case 3:togglePlay();break;case 4:playhead++;showEditor();break;case 5:showLayers();break;case 6:if(!layers.isEmpty()){layers.remove(layers.size()-1);selectedLayer=Math.max(0,layers.size()-1);showEditor();}break;case 7:Toast.makeText(this,"لا توجد عملية لإعادتها",Toast.LENGTH_SHORT).show();break;}});}body.addView(ctl);heading("الخط الزمني");TextView time=text("00:00:00     1       2       3       4       5",11,MUTED);body.addView(time,new LinearLayout.LayoutParams(-1,dp(24)));for(int i=0;i<layers.size();i++){final int ix=i;TextView track=button((i==selectedLayer?"◆  ":"◇  ")+layers.get(i).name+"     ━━━━━━━━━━━━━━━━━",i==selectedLayer);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,dp(42));tp.setMargins(0,dp(3),0,dp(3));body.addView(track,tp);track.setOnClickListener(v->{selectedLayer=ix;showEditor();});track.setOnLongClickListener(v->{new AlertDialog.Builder(this).setItems(new String[]{"خصائص","إعادة تسمية","حذف"},(d,w)->{if(w==0)showProperties();else if(w==1){EditText e=new EditText(this);e.setText(layers.get(ix).name);new AlertDialog.Builder(this).setTitle("اسم العنصر").setView(e).setPositiveButton("حفظ",(a,b)->{layers.get(ix).name=e.getText().toString();showEditor();}).setNegativeButton("إلغاء",null).show();}else{layers.remove(ix);selectedLayer=Math.max(0,layers.size()-1);showEditor();}}).show();return true;});}heading("إضافة عنصر");LinearLayout nav=row();String[] names={"Media","نص","Solid","Adjustment","Null","Shape","Vector","كاميرا"};for(String s:names){TextView b=text(s,11,WHITE);b.setGravity(Gravity.CENTER);nav.addView(b,new LinearLayout.LayoutParams(0,dp(52),1));b.setOnClickListener(v->{switch(s){case "Media":pickMedia();break;case "نص":addLayer("Text 1","Text",Color.WHITE);break;case "Solid":showColorPicker();break;case "Shape":addLayer("Shape 1","Shape",PURPLE);break;case "Adjustment":addLayer("Adjustment 1","Adjustment",Color.TRANSPARENT);break;case "Null":addLayer("Null 1","Null",Color.TRANSPARENT);break;case "Vector":addLayer("Vector 1","Shape",PURPLE);break;default:new AlertDialog.Builder(this).setMessage("طبقة الكاميرا ثلاثية الأبعاد غير مدعومة بعد.").setPositiveButton("حسنًا",null).show();}});}body.addView(nav);addButton(body,"خصائص العنصر · Edit",true,()->showProperties());addButton(body,"تصدير المشروع ↗",true,()->showExport());}
 void togglePlay(){playing=!playing;if(playing){handler.postDelayed(new Runnable(){public void run(){if(!playing)return;playhead++;if(page.equals("editor"))showEditor();handler.postDelayed(this,1000/Math.max(1,fps));}},1000/Math.max(1,fps));}else{handler.removeCallbacksAndMessages(null);}Toast.makeText(this,playing?"تشغيل المعاينة":"إيقاف المعاينة",Toast.LENGTH_SHORT).show();}
 void addLayer(String n,String t,int c){layers.add(new Layer(n,t,c));selectedLayer=layers.size()-1;showEditor();}void showColorPicker(){String[] colors={"أسود","أبيض","بنفسجي","أحمر","أزرق","أخضر"};int[] vals={Color.BLACK,Color.WHITE,PURPLE,Color.RED,Color.BLUE,Color.GREEN};new AlertDialog.Builder(this).setTitle("Solid Color").setItems(colors,(d,w)->addLayer("Solid Color "+(layers.size()+1),"Solid",vals[w])).show();}
