 class Stage extends View{Paint p=new Paint(3);float downX,downY;Stage(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.rgb(23,23,26));float top=getHeight()*.16f,bottom=getHeight()*.84f;c.drawColor(Color.rgb(23,23,26));p.setColor(Color.BLACK);c.drawRect(0,top,getWidth(),bottom,p);if(showGrid){p.setColor(Color.rgb(25,25,28));p.setStrokeWidth(dp(1));for(int x=0;x<getWidth();x+=dp(24))c.drawLine(x,top,x,bottom,p);for(int y=(int)top;y<bottom;y+=dp(24))c.drawLine(0,y,getWidth(),y,p);}if(!layers.isEmpty()){Layer l=layers.get(Math.min(selectedLayer,layers.size()-1));float cx=getWidth()/2f+posX*getWidth()/1920f,cy=getHeight()/2f+posY*getHeight()/1080f,w=getWidth()*.8f*scale/100f,h=(bottom-top)*.8f*scale/100f;p.setAlpha((int)(255*opacity/100));p.setColor(l.color);if(l.type.equals("Solid"))c.drawRect(cx-w/2,cy-h/2,cx+w/2,cy+h/2,p);else if(l.type.equals("Shape"))c.drawRect(cx-w*.25f,cy-h*.25f,cx+w*.25f,cy+h*.25f,p);else if(l.type.equals("Text")){p.setTextSize(dp(24));c.drawText(l.name,cx-w*.25f,cy,p);}p.setAlpha(255);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(PURPLE);c.drawRect(cx-w/2,cy-h/2,cx+w/2,cy+h/2,p);p.setStyle(Paint.Style.FILL);}}public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==0){downX=e.getX();downY=e.getY();return true;}if(e.getAction()==1||e.getAction()==2){posX+=(e.getX()-downX)*1920f/getWidth();posY+=(e.getY()-downY)*1080f/getHeight();downX=e.getX();downY=e.getY();invalidate();return true;}return true;}}
 void showProperties(){page="properties";base(layers.isEmpty()?projectName:layers.get(selectedLayer).name);heading("Attributes · الخصائص");field("الموقع X",-1920,1920,(int)posX,0);field("الموقع Y",-1080,1080,(int)posY,1);field("المقياس (%)",1,300,(int)scale,2);field("الدوران",-360,360,(int)rotation,3);field("الشفافية (%)",0,100,(int)opacity,4);addButton(body,"◆ إضافة إطار مفتاح",true,()->{try{JSONObject k=new JSONObject();k.put("time",playhead);k.put("x",posX);k.put("y",posY);k.put("scale",scale);k.put("rotation",rotation);k.put("opacity",opacity);keys.add(k);Toast.makeText(this,"تم حفظ إطار مفتاح عند "+playhead+" ثانية",Toast.LENGTH_SHORT).show();}catch(Exception ignored){}});addButton(body,"الترتيب والمحاذاة",false,()->new AlertDialog.Builder(this).setItems(new String[]{"توسيط أفقي","توسيط عمودي","إلى أعلى","إلى أسفل"},(d,w)->{if(w==0)posX=0;if(w==1)posY=0;if(w==2)posY=-400;if(w==3)posY=400;showProperties();}).show());addButton(body,"حذف العنصر",false,()->new AlertDialog.Builder(this).setMessage("حذف العنصر المحدد؟").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(d,w)->{if(!layers.isEmpty())layers.remove(selectedLayer);selectedLayer=Math.max(0,layers.size()-1);showEditor();}).show());addButton(body,"العودة إلى المحرر",false,()->showEditor());}
 void field(String label,int min,int max,int val,int id){LinearLayout box=column();box.setPadding(dp(12),dp(7),dp(12),dp(7));box.setBackground(shape(PANEL,0,10));box.addView(text(label+"   "+val,12,WHITE));SeekBar s=new SeekBar(this);s.setMax(max-min);s.setProgress(Math.max(0,Math.min(max-min,val-min)));s.setProgressTintList(android.content.res.ColorStateList.valueOf(PURPLE));box.addView(s);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean user){int v=p+min;switch(id){case 0:posX=v;break;case 1:posY=v;break;case 2:scale=v;break;case 3:rotation=v;break;case 4:opacity=v;break;}((TextView)box.getChildAt(0)).setText(label+"   "+v);if(stage!=null)stage.invalidate();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(76));lp.setMargins(0,dp(4),0,dp(4));body.addView(box,lp);}
 void showExport(){page="export";base("تصدير المشروع");body.addView(text(projectName,13,MUTED));heading("صيغة إخراج الفيديو");body.addView(text("الدقة",13,MUTED));Spinner re=spinner(new String[]{"720p","1080p","4K"});re.setSelection(resolution.equals("720p")?0:resolution.equals("4K")?2:1);body.addView(re);body.addView(text("معدل الإطارات (FPS)",13,MUTED));Spinner fr=spinner(new String[]{"24 FPS","30 FPS","60 FPS"});fr.setSelection(fps==24?0:fps==60?2:1);body.addView(fr);addButton(body,"📷 التقاط إطار (PNG)",false,()->savePng());addButton(body,"Export project file (.kf)",false,()->saveProjectFile());addButton(body,"تصدير الفيديو",true,()->{resolution=re.getSelectedItem().toString();fps=Integer.parseInt(fr.getSelectedItem().toString().split(" ")[0]);new AlertDialog.Builder(this).setTitle("محرك التصدير").setMessage("تم حفظ إعدادات التصدير. تصيير فيديو MP4 يحتاج إضافة محرك ترميز فيديو؛ لن يتم إنشاء فيديو وهمي.").setPositiveButton("حسنًا",null).show();});addButton(body,"إلغاء",false,()->showEditor());}
 void saveProjectFile(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,projectName.replaceAll("[^a-zA-Z0-9_-]","_")+".kf");try{startActivityForResult(i,201);}catch(Exception e){Toast.makeText(this,"تعذر فتح منتقي الملفات",Toast.LENGTH_LONG).show();}}
 void savePng(){if(stage==null){Toast.makeText(this,"افتح المحرر أولًا",Toast.LENGTH_SHORT).show();return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/png");i.putExtra(Intent.EXTRA_TITLE,"SQMotion_Frame.png");try{startActivityForResult(i,202);}catch(Exception e){Toast.makeText(this,"تعذر فتح منتقي الملفات",Toast.LENGTH_LONG).show();}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri u=data.getData();try{if(req==201){JSONObject obj=new JSONObject();obj.put("format","SQMotionStudio");obj.put("version",1);obj.put("name",projectName);obj.put("ratio",ratio);obj.put("resolution",resolution);obj.put("fps",fps);JSONArray arr=new JSONArray();for(Layer l:layers){JSONObject x=new JSONObject();x.put("name",l.name);x.put("type",l.type);x.put("color",l.color);arr.put(x);}obj.put("layers",arr);obj.put("keyframes",new JSONArray(keys));OutputStream o=getContentResolver().openOutputStream(u);o.write(obj.toString(2).getBytes("UTF-8"));o.close();Toast.makeText(this,"تم تصدير ملف المشروع .kf",Toast.LENGTH_LONG).show();}else if(req==202){Bitmap b=Bitmap.createBitmap(Math.max(1,stage.getWidth()),Math.max(1,stage.getHeight()),Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);stage.draw(c);OutputStream o=getContentResolver().openOutputStream(u);b.compress(Bitmap.CompressFormat.PNG,100,o);o.close();b.recycle();Toast.makeText(this,"تم حفظ إطار PNG",Toast.LENGTH_LONG).show();}else if(req==203){addLayer("Imported Media","Media",Color.DKGRAY);layers.get(selectedLayer).uri=u;}else if(req==204){InputStream in=getContentResolver().openInputStream(u);ByteArrayOutputStream buf=new ByteArrayOutputStream();byte[] chunk=new byte[4096];int count;while((count=in.read(chunk))!=-1)buf.write(chunk,0,count);in.close();JSONObject obj=new JSONObject(new String(buf.toByteArray(),"UTF-8"));projectName=obj.optString("name","Imported Project");ratio=obj.optString("ratio","16:9");resolution=obj.optString("resolution","1080p");fps=obj.optInt("fps",30);layers.clear();JSONArray arr=obj.optJSONArray("layers");if(arr!=null)for(int j=0;j<arr.length();j++){JSONObject x=arr.getJSONObject(j);layers.add(new Layer(x.optString("name","Layer"),x.optString("type","Solid"),x.optInt("color",Color.BLACK)));}if(layers.isEmpty())layers.add(new Layer("Solid Color 1","Solid",Color.BLACK));keys.clear();JSONArray kk=obj.optJSONArray("keyframes");if(kk!=null)for(int j=0;j<kk.length();j++)keys.add(kk.getJSONObject(j));if(!projects.contains(projectName))projects.add(0,projectName);persist();selectedLayer=0;showEditor();Toast.makeText(this,"تم استيراد المشروع",Toast.LENGTH_LONG).show();}}catch(Exception e){Toast.makeText(this,"تعذر الحفظ: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
